update public.lessons set summary = 'Dòng điện xoay chiều có các tác dụng nhiệt, phát sáng, từ và sinh lí; đo bằng ampe kế, vôn kế xoay chiều.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'objective', 'Nêu được các tác dụng của dòng điện xoay chiều và lấy ví dụ.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.content = 'Nêu được các tác dụng của dòng điện xoay chiều và lấy ví dụ.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'objective', 'Nhận biết ampe kế, vôn kế xoay chiều và cách sử dụng.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.content = 'Nhận biết ampe kế, vôn kế xoay chiều và cách sử dụng.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'objective', 'Có ý thức an toàn khi sử dụng điện.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.content = 'Có ý thức an toàn khi sử dụng điện.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'requirement', 'Lấy ví dụ để chứng tỏ dòng điện xoay chiều có tác dụng: nhiệt, phát sáng, tác dụng từ, tác dụng sinh lí.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.content = 'Lấy ví dụ để chứng tỏ dòng điện xoay chiều có tác dụng: nhiệt, phát sáng, tác dụng từ, tác dụng sinh lí.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'knowledge', 'text', '1. Các tác dụng của dòng điện xoay chiều', '• Tác dụng nhiệt: bàn là, nồi cơm điện, ấm siêu tốc nóng lên khi có dòng điện chạy qua.
• Tác dụng phát sáng (quang): bóng đèn sợi đốt, đèn LED, đèn huỳnh quang phát sáng.
• Tác dụng từ: nam châm điện dùng dòng xoay chiều hút được sắt; lực từ đổi chiều khi dòng điện đổi chiều (kim nam châm đặt gần dây dẫn sẽ dao động, rung, không quay hẳn về một phía).
• Tác dụng sinh lí: dòng điện xoay chiều qua cơ thể người gây co giật cơ, có thể gây nguy hiểm đến tính mạng.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.section = 'knowledge' and x.title = '1. Các tác dụng của dòng điện xoay chiều');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'knowledge', 'text', '2. Đo cường độ dòng điện và hiệu điện thế xoay chiều', 'Dùng ampe kế và vôn kế xoay chiều (có kí hiệu AC hoặc dấu ~). Giá trị đo được là giá trị hiệu dụng; khi mắc vào mạch không cần phân biệt chốt (+) và (−).
Hiệu điện thế hiệu dụng của mạng điện gia đình ở Việt Nam là 220 V.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.section = 'knowledge' and x.title = '2. Đo cường độ dòng điện và hiệu điện thế xoay chiều');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'knowledge', 'text', '3. An toàn điện', 'Không chạm vào dây điện trần, ổ cắm khi tay ướt; dùng thiết bị có vỏ cách điện, nối đất; lắp cầu dao chống giật (aptomat chống dòng rò).', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.section = 'knowledge' and x.title = '3. An toàn điện');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'experiment', 'text', 'Thí nghiệm SGK: Tác dụng của dòng điện xoay chiều', 'Tác dụng nhiệt, phát sáng: mắc bóng đèn vào nguồn xoay chiều → đèn nóng lên và sáng.
Tác dụng từ: đặt kim nam châm gần cuộn dây có dòng điện xoay chiều → kim nam châm dao động; nam châm điện dùng dòng xoay chiều vẫn hút được đinh sắt.
Đo: dùng vôn kế, ampe kế xoay chiều (kí hiệu AC hoặc ~).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK: Tác dụng của dòng điện xoay chiều');

